// ⓪ ENTRADA · mantenimiento diario del portero · CC#2 · 2026-10-10.
//  · por HORARIO: corre de verdad (dry_run=false), para todos los clientes activos.
//  · a mano (webhook): exige la llave de despacho y `dry_run` BOOLEANO OBLIGATORIO; `client_id` (uuid) opcional limita el alcance.
// 🔴 Sin llave, o sin `dry_run` booleano en la entrada a mano, el flujo SE DETIENE aquí: no se lee ni se escribe nada.
let w = null
try { w = $('Webhook · a mano (con llave)').first() } catch (e) { w = null }
const base = { workflow_id: String($workflow.id), workflow_execution_id: String($execution.id) }
if (!w) return [{ json: { ...base, via: 'horario', dry_run: false, client_id: null } }]
const h = w.json || {}
const esperada = String($env.SALA_DISPATCH_KEY || '')
const recibida = String((h.headers || {})['x-sala-dispatch-key'] || '')
if (!esperada || recibida !== esperada) throw new Error('DIARIO_SIN_LLAVE · falta o no coincide x-sala-dispatch-key (o SALA_DISPATCH_KEY no está configurada) · se DETIENE')
const b = h.body || {}
if (typeof b.dry_run !== 'boolean') throw new Error('DIARIO_DRY_RUN_OBLIGATORIO · `dry_run` es obligatorio y debe ser true o false · se DETIENE')
if (b.client_id !== undefined && (typeof b.client_id !== 'string' || !/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(b.client_id))) throw new Error('DIARIO_CLIENTE_INVALIDO · `client_id` debe ser un uuid · se DETIENE')
return [{ json: { ...base, via: 'a mano', dry_run: b.dry_run, client_id: b.client_id || null } }]

// ① SEPARAR EL PLAN EN UN ELEMENTO POR CLIENTE. Si el plan falló, se DICE (un fallo nunca se lee como «no hay clientes»).
const e = $('⓪ Entrada').first().json
const r = $input.first().json || {}
const p = r.body ? r.body : r
if (!p || p.error || !Array.isArray(p.clientes)) return [{ json: { ...e, cliente: null, falla: 'El plan falló: ' + String((p && (p.error || p.detalle)) || 'sin respuesta') + ' ' + String((p && p.detalle) || '') } }]
if (!p.clientes.length) return [{ json: { ...e, cliente: null, falla: null, sin_clientes: true, excluidos: p.excluidos || [] } }]
return p.clientes.map((c) => ({ json: { ...e, cliente: c.client_id, nombre: c.nombre, acciones: (c.plan && c.plan.hacer) || [], omitidas: (c.plan && c.plan.omitidas) || [], no_cubiertas: (c.plan && c.plan.no_cubiertas) || [], gastado_hoy_usd: c.gastado_hoy_usd, falla: null } }))

// ② LA AMPLIACIÓN (paso 1, lo que el flujo de la mañana NO cubre) · ejecuta SOLO lo que la ruta `plan` dejó en `acciones` de CADA cliente (ya recortado al tope de US$ 1,00 por cliente y día).
// 🔴 Con `dry_run` NO llama a nadie. 🔴 Una llamada al Servicio por acción, SIN reintento (cada una paga). 🔴 Dos fallas seguidas por cliente ⇒ para a ese cliente. Este nodo NO lee ninguna tabla: lo decide la ruta.
// El Servicio guarda lo crudo en `apify_raw` (destino `respuesta`); lo que cuesta se mide con la API de Apify y se informa a `correr`, que lo compara con el tope.
// Procesa TODOS los elementos (uno por cliente), en orden, y devuelve uno por cliente.
const N8N = 'https://n8n-production-72be.up.railway.app'
const http = async (o) => this.helpers.httpRequest({ json: true, returnFullResponse: true, ignoreHttpStatusErrors: true, timeout: 140000, ...o })
const salidas = []
for (const item of $input.all()) {
  const e = item.json
  const salida = { ...e, ampliacion: { hecho: false, llamadas: [], gasto_usd: 0, parado: null } }
  if (e.falla || !e.cliente) { salidas.push({ json: salida }); continue }
  if (e.dry_run === true) { salida.ampliacion.nota = 'dry_run: no se llamó a ningún proveedor'; salidas.push({ json: salida }); continue }
  let seguidasConFalla = 0
  for (const a of e.acciones || []) {
    const t0 = Date.now()
    const r = await http({ url: N8N + '/webhook/apify-service-workflow', method: 'POST', headers: { 'Content-Type': 'application/json' },
      body: { client_id: e.cliente, apify_function: a.funcion, params: a.params, destination: 'respuesta', dry_run: false, metadata: { ...(a.metadata || {}), calling_workflow_id: e.workflow_id } } })
    const b = r.body && typeof r.body === 'object' ? r.body : {}
    const ll = { fuente: a.fuente, funcion: a.funcion, hecho: r.statusCode === 200 && b.ok === true, http: r.statusCode, ms: Date.now() - t0, apify_run_id: b.apify_run_id || null, usd_max: a.usd_max, medido: a.medido }
    if (!ll.hecho) ll.error = String(b.error || b.message || b.validation_errors || '').slice(0, 160)
    let costo = typeof a.usd_max === 'number' ? a.usd_max : 0 // sin dato real, se cuenta el MÁXIMO (nunca 0 para decir «no sé»)
    if (ll.apify_run_id && $env.APIFY_API_TOKEN) {
      const u = await http({ url: 'https://api.apify.com/v2/actor-runs/' + ll.apify_run_id + '?token=' + $env.APIFY_API_TOKEN, method: 'GET', headers: {} })
      const d = u.body && u.body.data
      if (d && d.usageTotalUsd !== undefined) { ll.costo_real_usd = Number(d.usageTotalUsd); costo = ll.costo_real_usd }
    }
    ll.costo_contado_usd = costo
    salida.ampliacion.gasto_usd = Number((salida.ampliacion.gasto_usd + costo).toFixed(6))
    salida.ampliacion.llamadas.push(ll)
    seguidasConFalla = ll.hecho ? 0 : seguidasConFalla + 1
    if (seguidasConFalla >= 2) { salida.ampliacion.parado = 'dos_fallas_seguidas'; break }
  }
  salida.ampliacion.hecho = salida.ampliacion.llamadas.length > 0 && salida.ampliacion.llamadas.every((l) => l.hecho)
  salidas.push({ json: salida })
}
return salidas

// ③ ARMAR EL PEDIDO A `correr` (pasos 2, 3 y 5) de CADA cliente. Pasa el gasto REAL de la ampliación para que la ruta lo compare con el tope. Sin cliente o con falla del plan no hay pedido (queda «saltado»).
return $input.all().map((item) => {
  const e = item.json
  if (e.falla || !e.cliente) return { json: { ...e, correr_body: null } }
  return { json: { ...e, correr_body: { client_id: e.cliente, dry_run: e.dry_run, workflow_id: e.workflow_id, workflow_execution_id: e.workflow_execution_id, gasto_ampliacion_usd: (e.ampliacion && e.ampliacion.gasto_usd) || 0 } } }
})

// ④ CIERRE · junta lo de todos los clientes en una línea por cliente y dice qué pasó. Un error de la ruta o del plan se DICE. De las reseñas y comentarios solo hay señales agregadas (sin nombre ni texto).
// Los elementos del paso ③ y las respuestas de `correr` van EN EL MISMO ORDEN (el flujo es lineal, sin ramas que filtren). Un elemento sin pedido real («saltado») se ignora aunque `correr` haya contestado 400.
const respuestas = $input.all().map((i) => i.json)
const pedidos = $('③ Pedido a correr').all().map((i) => i.json)
const clientes = pedidos.map((pedido, k) => {
  const saltado = pedido.correr_body === null
  const r0 = respuestas[k] || {}
  const r = r0.body ? r0.body : r0
  return {
    cliente: pedido.cliente || null,
    plan_fallo: pedido.falla || null,
    ampliacion: pedido.ampliacion ? { hecho: pedido.ampliacion.hecho, gasto_usd: pedido.ampliacion.gasto_usd, parado: pedido.ampliacion.parado, llamadas: (pedido.ampliacion.llamadas || []).length } : null,
    estado: saltado ? 'saltado' : r.estado || 'sin_respuesta',
    ok: saltado ? null : r.ok === true,
    fuentes: !saltado && Array.isArray(r.fuentes) ? r.fuentes.map((f) => f.fuente + ':' + f.accion) : [],
    oportunidades: !saltado && Array.isArray(r.oportunidades) ? r.oportunidades.length : 0,
    gasto: saltado ? null : r.gasto || null,
    errores: !saltado && Array.isArray(r.errores) ? r.errores : [],
    detalle: saltado ? null : r.detalle || r.error || null,
  }
})
const e = $('⓪ Entrada').first().json
const malo = clientes.some((c) => c.plan_fallo || (c.estado !== 'saltado' && (c.errores.length > 0 || (c.ok === false && c.estado !== 'ya_corrio_hoy'))))
return [{ json: { fin: malo ? 'con_errores' : 'hecho', via: e.via, dry_run: e.dry_run, clientes } }]
